mapper.sql:


AND (
    (
        s.kind = 'ALL_DAY'
        AND s.start_date < s.end_date
        AND s.start_date <= #{endDate}
        AND s.end_date > #{startDate}
    )
    OR
    (
        s.kind = 'DATED'
        AND s.start_at < s.end_at
        AND s.start_at < #{rangeEndAt}
        AND s.end_at > #{rangeStartAt}
    )
)

mapper.select:
SELECT s.id, s.kind, s.start_at, s.end_at, s.start_date, s.end_date, s.title
FROM schedule s
WHERE s.user_id = #{userId}

SELECT id, kind, start_at, end_at, start_date, end_date, title
FROM schedule
WHERE id = #{id} AND user_id = #{userId}

mapper.update:
    UPDATE calendar_event
SET
    color = #{calendarEvent.color},
    memo = #{calendarEvent.memo}
WHERE id = #{calendarEvent.id}
  AND EXISTS(
      SELECT 1
      FROM schedule s
      WHERE s.id = calendar_event.schedule_id
        AND s.user_id = #{userId}
  )

mapper.delete:
DELETE FROM calendar_event c
WHERE c.id = #{id}
AND EXISTS(
    SELECT 1
    FROM schedule s
    WHERE s.id = c.schedule_id
    AND s.user_id = #{userId}
)
